import type { SeriesIndex } from "../core/src/rba/series-index";

/**
 * Write the series index as the TypeScript module that ships in the library.
 *
 * The output is valid but unformatted: the caller runs the project formatter
 * on the file.
 *
 * @param index - The series index.
 * @returns The module source.
 */
export const renderSeriesIndex = (index: SeriesIndex): string =>
  [
    "// Generated by `bun run rba:index` from the RBA statistical tables page.",
    "// Do not edit by hand: run the build again.",
    "",
    'import type { SeriesIndex } from "./series-index";',
    "",
    "/** The series index that ships with the library (ADR 0010). */",
    `export const SERIES_INDEX: SeriesIndex = ${JSON.stringify(index, null, 2)};`,
    "",
  ].join("\n");
